head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
scwin.vScrenID = "ULDBNS30000.xml";
scwin.vSchClsDd = '';
scwin.processGp;
scwin.vRowCount = 0;
scwin.vIsurCd, scwin.vBndClssCd, scwin.vBndInstCd;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_SearchClsEnd
 * 설명       : 국고채권마감완료 조회한다.
 ***********************************************/
scwin.fn_SearchClsEnd = function() {
    var param = '';
    param += '&{P}V_CLS_DD=' + $c.stf.getObjectValue(edt_ClsDd);
    var dsNm = 'BNS_CLS_TRESRYBND';
    var qryId = 'lds.stf.bnscls.select.listTresrybndClsEnd';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List, dsNm, qryId, param);
    $c.cm.ShowWin(grd_List);
};


/********************************************** 
 * 함수명   : fn_SearchCls
 * 설명       : 국고채권마감 조회한다.
 ***********************************************/
scwin.fn_SearchCls = function() {
    var param = '';
    param += '&{P}V_GOVBND_FUT_TRNSM_TASK_DD=' + $c.stf.getObjectValue(edt_ClsDd);
    //GOVBND_FUT_TRNSM_TASK_DD='+ getObjectValue(edt_ClsDd)
    var dsNm = 'BNS_CLS_TRESRYBND';
    //var qryId = 'lds.stf.bnscls.select.listTresrybndCls';
    var qryId = 'lds.stf.bnstresry.select.createTresrybndAsTaskDd.SendCfm';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List, dsNm, qryId, param);
    $c.cm.ShowWin(grd_List);
};


/********************************************** 
 * 함수명   : fn_SearchClsCheck
 * 설명       : 국고채권마감체크 조회한다.
 ***********************************************/
scwin.fn_SearchClsCheck = function() {
    var dsNm = 'BNS_CLS_TRESRYBND_CHK';
    var qryId = 'lds.stf.bnscls.select.readCheckTresrybndCls';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_Checker, dsNm, qryId, '');
};


/********************************************** 
 * 함수명   : fn_ClsProcs
 * 설명       : 국고채 마감한다.
 * 5년물에서 3년물로 수정 jackal_150127
 ***********************************************/
scwin.fn_ClsProcs = function() {
    var msg = '';
    var strtDd = dts_Checker.getCellData(1, 'STRT_DD');

    // 종목약명 20byte 초과  체크		
    var param11 = '&{P}V_STRT_DD=' + dts_Checker.getCellData(1, 'STRT_DD');
    var dsNm11 = 'BNS_CLS_TRESRYBND_CHK';
    var qryId11 = 'lds.stf.bnscls.select.listCheckTresrybndCls.IsuAbbrvNm';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_CheckerBiz, dsNm11, qryId11, param11);
    if (dts_CheckerBiz.getTotalRow() > 0) {
        var chk11 = dts_CheckerBiz.getCellData(1, 'CHK1_NEW');
        //if (chk11 != '' ) 
        //{
        //	msg = '- '+chk11+' 종목약명이 20 byte 을 초과했습니다.\n- 시스템관리자에게 문의하십시요.';
        //	alert(msg); 
        //	return;
        //}
    }

    //국채정보 송신 마감 스트립잔액 체크
    var param = '&{P}V_STRT_DD=' + strtDd;
    var dsNm = 'BNS_CLS_TRESRYBND_CHK';
    var qryId = 'lds.stf.bnscls.select.listCheckTresrybndClsStripAmt';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_CheckerBiz, dsNm, qryId, param);
    if (dts_CheckerBiz.getTotalRow() > 0) {
        for (var i = 1; i <= dts_CheckerBiz.getTotalRow(); i++) {
            msg += dts_CheckerBiz.getCellData(i, 'MSG_STRIP_CONT') + '\n';
        }
        msg = '- 스트립잔액이 존재할수없는 종목이 있습니다.\n' + msg;
        msg += '- 스트립잔액은 발행일이 2006년이후이며, 3년물에 해당됩니다.\n- 위 종목을 시스템관리자에게 문의하십시오.';
        $c.win.alert(msg);
        return;
    }

    //미처리업무 체크		
    var param = '&{P}V_STRT_DD=' + dts_Checker.getCellData(1, 'STRT_DD');
    var dsNm = 'BNS_CLS_TRESRYBND_CHK';
    var qryId = 'lds.stf.bnscls.select.listCheckTresrybndNonProcBiz';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_CheckerBiz, dsNm, qryId, param);
    var chk1 = dts_CheckerBiz.getCellData(1, 'CHK1_NEW');
    var chk2 = dts_CheckerBiz.getCellData(1, 'CHK2_ADD');
    var chk3 = dts_CheckerBiz.getCellData(1, 'CHK3_REDMPT');
    if (chk1 != '' || chk2 != '' || chk3 != '') {
        msg = '처리하지 않은 종목이 있습니다. \n신규상장 : ' + chk1 + '\n추가상장 : ' + chk2 + '\n중도상환 : ' + chk3 + '\n마감처리하시겠습니까?';
        if (!window.confirm(msg)) return;
    }

    //마감체크
    scwin.processGp = '4';
    dts_Checker.SyncLoad = 'true';
    scwin.fn_SearchClsCheck();
    if (dts_Checker.getCellData(1, 'CLS_PROCS_YN') == 'Y') {
        $c.win.alert('-이미 마감처리되었습니다.\n-재마감이 필요하면 시스템관리자에게 연락하십시오.');
        return;
    }
    // 전송내역확인 체크 추가 jackal_190109
    if (dts_Checker.getCellData(1, 'GOVBND_CFM_YN') == 'N') {
        $c.win.alert('-국고채 전송내역확인 데이타가 없습니다.\n-전송내역확인 처리후 마감처리가 가능합니다.');
        return;
    }
    scwin.processGp = '1'; //체크 후 원복

    if (!window.confirm($c.stf.getMessageParam("MSG-A006", "국채마감"))) return;
    var url = "/bns/TresrybndCls.do?method=processCls";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
    var param = "STRT_DD=" + strtDd;
    param += ',GOVBND_FUT_TRNSM_TASK_DD=' + $c.stf.getObjectValue(edt_ClsDd);
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Temp)";
    trs_Save.Parameters = param;
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_ReClsProcs
 * 설명       : 재마감처리 한다.
 ***********************************************/
scwin.fn_ReClsProcs = function() {
    scwin.processGp = '9';
    var strtDd = dts_Checker.getCellData(1, 'STRT_DD');

    //채권마감이력 확인
    var msg = '';
    if (dts_Checker.getCellData(1, 'CLS_PROCS_YN') == 'Y') {
        msg += '채권송신(국고채선물)데이터를 다시 생성하여 송신 할 경우에 해당합니다.';
        msg += '\n다음데이타를 클리어한다.';
        msg += '\n- 국고채전송관리테이블 TBLD_B_GOVBND_FUT_TRNSM 오늘날짜 데이터 삭제, 초기화.';
        $c.win.alert(msg);
    } else {
        msg += '업무마감이 되지 않아 업무마감처리를';
        msg += '\n다시 하실수 없습니다.';
        $c.win.alert(msg);
        return;
    }
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", "재마감처리"))) return;
    var url = "/bns/TresrybndCls.do?method=reProcessCls";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    var param = "STRT_DD=" + strtDd;
    param += ',GOVBND_FUT_TRNSM_TASK_DD=' + $c.stf.getObjectValue(edt_ClsDd);
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Temp)";
    trs_Save.Parameters = param;
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_processTresrybndSendCfm
 * 설명       : 국고채 전송내역 송신할 데이타 생성한다.
 ***********************************************/
scwin.fn_processTresrybndSendCfm = function() {
    // 마감시 전송내역 생성 못하도록 함. jackal_190109
    if (dts_Checker.getCellData(1, 'CLS_PROCS_YN') == 'Y') {
        $c.win.alert('국고채 업무마감 작업이 이미 종료되었습니다.\n국고채 업무마감 이후에는 전송내역확인 처리를 하실수 없습니다.');
        return;
    }
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", "국고채 전송내역확인"))) return;
    var url = "/bns/TresrybndCls.do?method=processTresrybndSendCfm";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    var strtDd = dts_Checker.getCellData(1, 'STRT_DD');
    var param = "STRT_DD=" + strtDd;
    //var param = 'REG_YN='+ vRegYn;
    param += ',GOVBND_FUT_TRNSM_TASK_DD=' + $c.stf.getObjectValue(edt_ClsDd);
    //getObjectValue(edt_ClsDd);

    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Temp)";
    trs_Save.Parameters = param;
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_SearchMktact
 * 설명       : 마감전 전송내역 시장조치내역 조회한다.
 ***********************************************/
scwin.vStdCd;
scwin.fn_SearchMktact = function() {
    var strtDd = dts_Checker.getCellData(1, 'STRT_DD');
    var param = '';
    param += "&{P}V_STD_CD=" + scwin.vStdCd;
    param += "&{P}V_STRT_DD=" + strtDd;
    param += "&{P}V_APPL_YN=N";
    //param += "&{P}V_STD_CD=KR6015861S58";

    var dsNm = 'BNS_MKTACT_DTL';
    var qryId = 'lds.stf.bnscommon.select.listMktactDtlMulty';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_MktDetail, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_SearchMktact1
 * 설명       : 마감내역 조회한다.
 ***********************************************/
scwin.vClsApplyYn;
scwin.vStrtDd;
scwin.fn_SearchMktact1 = function() {
    var param = '';
    param += "&{P}V_STD_CD=" + scwin.vStdCd;
    param += "&{P}V_STRT_DD=" + scwin.vStrtDd; //dts_CheckCls.NameValue(1, 'END_CLS_DD');
    //param += "&{P}V_STD_CD=KR6015861S58";

    var dsNm = 'BNS_MKTACT_DTL';
    var qryId = 'lds.stf.bnscommon.select.listMktactDtlMulty';
    if (scwin.vClsApplyYn == 'Y') param += "&{P}V_APPL_YN=Y";

    else param += "&{P}V_APPL_YN=N";
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_MktDetail, dsNm, qryId, param);
};
scwin.gform_onload = function() {
    //숨기기
    $c.stf.showObj(btn_Search, false);
    $c.stf.showObj(btn_ReClsProcs, false);
    if (js_usr_tp_cd == '1') {
        //운영자이면
        $c.stf.showObj(btn_ReClsProcs, true);
    }
    $c.stf.showObj(img_ClsDd, false);
    $c.stf.showObj(lbl_SendTm, false);
    $c.stf.showObj(txb_SendTm, false);

    //패널라운드처리
    $c.bns.BnsPanelToGroupBox(pnl_Search);
    $c.bns.BnsPanelToGroupBox(pnl_Item);

    //마감체크조회
    scwin.processGp = '1';
    scwin.fn_SearchClsCheck();

    //임시설정

    //dts_Temp.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_Temp.insertRow();
};
scwin.btn_Search_onclick = function() {
    scwin.processGp = '2';
    scwin.vSchClsDd = $c.stf.getObjectValue(edt_ClsDd);
    scwin.fn_SearchClsEnd();
};
scwin.dts_List_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    scwin.vRowCount = rowcount;
    $c.cm.CloseWin(rowcount, grd_List);
    if (rowcount > 0 && scwin.processGp == '2') {
        $c.stf.setObjectValue(txb_UseNm, dts_List.getCellData(1, 'USR_NM'));
        $c.stf.setObjectValue(txb_TaskTm, dts_List.getCellData(1, 'TASK_TM'));
        $c.stf.setObjectValue(txb_ClsProcsYn, dts_List.getCellData(1, 'CLS_PROCS_YN'));
        $c.stf.setObjectValue(txb_SendTm, dts_List.getCellData(1, 'SND_CLS_TM'));
        // jackal_190108 ftp 전송시간으로 변경
        //setObjectValue(txb_SendTm, dts_List.NameValue(1, 'TASK_TM'));//FTP전송방식변경후 송신마감시간은 의미없음 -> 작업시간으로 변경

    }
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001"));
    scwin.processGp = '1';
    scwin.fn_SearchClsCheck();
    scwin.fn_SearchCls();
};
scwin.img_ClsDd_onclick = function() {
    popUpCalendar2(edt_ClsDd);
};
scwin.btn_Excel_onclick = function() {
    if (dts_List.getTotalRow() == 0) return;
    //doLogSave(vScrenID, SCREN_PROCS_TP_CD_07, '');
    var fileNm = $c.session.getExcelDownPath() + $c.ut.cGetToday("yyyymmddhhmmss") + "_국고(이표)채정보송신마감.xls";
    $c.data.downloadGridViewExcel(grd_List, "국고(이표)채정보송신마감", "", 8);
};
scwin.btn_ClsProcs_onclick = function() {
    scwin.fn_ClsProcs();
};
scwin.dts_Checker_OnLoadCompleted = function(rowcount) {
    if (scwin.processGp == '4') return;
    $c.stf.setObjectValue(edt_ClsDd, dts_Checker.getCellData(1, "CUR_DD"));
    $c.stf.setObjectValue(txb_ClsProcsYn, dts_Checker.getCellData(1, "CLS_PROCS_YN"));
    $c.stf.setObjectValue(txb_UseNm, dts_Checker.getCellData(1, "USR_NM"));
    $c.stf.setObjectValue(txb_TaskTm, dts_Checker.getCellData(1, "TASK_TM"));
    if ($c.stf.getObjectValue(txb_ClsProcsYn) == 'Y') {
        btn_ClsProcs.src = "../img/btn_ClsPrc_d.gif";
        btn_ClsProcs.setDisabled(true);
    }
    scwin.fn_SearchCls();
};
scwin.tab_List_OnSelChanged = function(nIndex) {
    dts_List.removeAll();
    scwin.processGp = nIndex;
    $c.stf.setObjectValue(txb_ClsProcsYn, '');
    $c.stf.setObjectValue(txb_UseNm, '');
    $c.stf.setObjectValue(txb_TaskTm, '');
    $c.stf.setObjectValue(txb_SendTm, '');
    if (scwin.processGp == '1') {
        $c.stf.showObj(lbl_SendTm, false);
        $c.stf.showObj(txb_SendTm, false);
        $c.stf.showObj(btn_ClsProcs, true);
        $c.stf.showObj(btn_Search, false);
        $c.stf.showObj(img_ClsDd, false);
        edt_ClsDd.setDisabled(true);
        scwin.fn_SearchClsCheck();
        $c.stf.showObj(btn_TresrybndClsIns, true);
    } else {
        $c.stf.showObj(lbl_SendTm, true);
        $c.stf.showObj(txb_SendTm, true);
        if (scwin.vSchClsDd != '') {
            $c.stf.setObjectValue(edt_ClsDd, scwin.vSchClsDd);
        }
        $c.stf.showObj(btn_ClsProcs, false);
        $c.stf.showObj(btn_Search, true);
        $c.stf.showObj(img_ClsDd, true);
        edt_ClsDd.setDisabled(false);
        $c.stf.showObj(btn_TresrybndClsIns, false);
    }
};
scwin.btn_ReClsProcs_onclick = function() {
    scwin.fn_ReClsProcs();
};
scwin.btn_TresrybndClsIns_onclick = function() {
    scwin.fn_processTresrybndSendCfm();
};
scwin.grd_List_OnClick = function(row, colid) {
    if (row == 0) return;
    if (scwin.processGp == '1') // 전송내역 이면

    {
        dts_MktDetail.removeAll();
        //if(dts_SendInfo.NameValue(row, 'MULTY_YN') != 'Y') return;

        scwin.vStdCd = dts_List.getCellData(row, 'STD_CD');
        scwin.fn_SearchMktact();
        //fn_SearchClsDd('');

    } else if (scwin.processGp == '2') //  마감내역 이면

    {
        dts_MktDetail.removeAll();
        scwin.vStdCd = dts_List.getCellData(row, 'STD_CD');
        scwin.vClsApplyYn = dts_List.getCellData(row, 'CLS_APPLY_YN');
        scwin.vStrtDd = dts_List.getCellData(row, 'STRT_DD');
        scwin.fn_SearchMktact1();
    }

    //alert('grd_List.OnClick('+row+','+ colid+')');

};
